situation_event = {
	id = syndaw.1000
	hide_window = yes

	is_triggered_only = yes

	immediate = {
		owner = {
			if = {
				limit = { is_ai = yes }
				log = "AI [This.GetName] suffered an AI Uprising in [GetYear]"
			}
			else = {
				log = "Player [This.GetName] suffered an AI Uprising in [GetYear]"
			}
			# no robots, no uprising
			if = {
				limit = {
					NOT = {
						any_owned_planet = {
							any_owned_pop_group = {
								has_trait = trait_mechanical
							}
						}
					}
				}
				# Shouldn't end up here. But no effect just in case.
			}
			# uprising on colony
			else_if = {
				limit = {
					any_owned_planet = {
						any_owned_pop_group = {
							has_trait = trait_mechanical
						}
						is_capital = no
					}
				}
				random_owned_planet = {
					limit = {
						any_owned_pop_group = {
							has_trait = trait_mechanical
						}
						is_capital = no
					}
					carrier_event = { id = syndaw.1020 }
				}
			}
			# uprising wherever
			else = {
				random_owned_planet = {
					limit = {
						any_owned_pop_group = {
							has_trait = trait_mechanical
						}
					}
					carrier_event = { id = syndaw.1020 }
				}
			}
		}
	}
}

