carrier_event = {
	id = syndaw.1330
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		FROM = {
			has_valid_civic = civic_machine_terminator
		}
		exists = fromfrom #crisis.202 can remove the last pop
		FROMFROM = {
			NOR = {
				has_trait = trait_mechanical
				has_trait = trait_machine_unit
			}
		}
		is_controlled_by = FROM
	}

	immediate = {
		if = {
			limit = {
				exists = leader
				leader = {
					has_trait = leader_trait_judicial_execution
				}
			}
			while = {
				count = value:per_100_local_pop_amount
				FROM = {
					add_monthly_resource_mult = {
						resource = unity
						value = 4
						min = 10
						max = 200
					}
				}
			}
		}
		else_if = {
			limit = {
				is_sector_capital = no
				NOT = { exists = leader }
				exists = sector
				sector.sector_capital = {
					exists = leader
					leader = {
						has_trait = leader_trait_judicial_execution
					}
				}
			}
			while = {
				count = value:per_100_local_pop_amount
				FROM = {
					add_monthly_resource_mult = {
						resource = unity
						value = 3
						min = 7
						max = 150
					}
				}
			}
		}
		else = {
			if = {
				limit = {
					from = {
						has_origin = origin_nomadic_purger
						exists = overlord
					}
				}
				while = {
					count = value:per_100_local_pop_amount
					FROM.overlord = {
						add_monthly_resource_mult = {
							resource = unity
							value = 2
							min = 5
							max = 100
						}
					}
				}
			}
			else = {
				while = {
					count = value:per_100_local_pop_amount
					FROM = {
						add_monthly_resource_mult = {
							resource = unity
							value = 2
							min = 5
							max = 100
						}
					}
				}
			}
		}
	}
}
